dashboard.definition:
{
  "title": "AI provider setup",
  "description": "Configure optional OpenAI, Cisco, Azure, or custom model integration. No API keys on this page.",
  "defaults": {},
  "inputs": {
    "input_cfg_mode": {
      "type": "input.dropdown",
      "title": "AI mode",
      "options": {
        "token": "tok_cfg_mode",
        "defaultValue": "off",
        "items": [
          {
            "label": "Off \u2014 local briefing only",
            "value": "off"
          },
          {
            "label": "Provider \u2014 queue ASK to your gateway",
            "value": "provider"
          }
        ]
      }
    },
    "input_cfg_provider": {
      "type": "input.dropdown",
      "title": "Provider",
      "options": {
        "token": "tok_cfg_provider",
        "defaultValue": "none",
        "items": [
          {
            "label": "None",
            "value": "none"
          },
          {
            "label": "OpenAI",
            "value": "openai"
          },
          {
            "label": "Cisco AI Defense",
            "value": "cisco"
          },
          {
            "label": "Azure OpenAI",
            "value": "azure"
          },
          {
            "label": "Anthropic",
            "value": "anthropic"
          },
          {
            "label": "Custom OpenAI-compatible",
            "value": "custom"
          }
        ]
      }
    },
    "input_cfg_model": {
      "type": "input.text",
      "title": "Model id (example gpt-4o-mini)",
      "options": {
        "token": "tok_cfg_model",
        "defaultValue": "none"
      }
    },
    "input_cfg_endpoint": {
      "type": "input.text",
      "title": "Chat endpoint URL (none = provider default)",
      "options": {
        "token": "tok_cfg_endpoint",
        "defaultValue": "none"
      }
    },
    "input_cfg_inbox_index": {
      "type": "input.text",
      "title": "HEC reply index",
      "options": {
        "token": "tok_cfg_inbox_index",
        "defaultValue": "main"
      }
    },
    "input_cfg_inbox_sourcetype": {
      "type": "input.text",
      "title": "HEC reply sourcetype",
      "options": {
        "token": "tok_cfg_inbox_sourcetype",
        "defaultValue": "derek_health_ai"
      }
    },
    "input_cfg_save": {
      "type": "input.text",
      "title": "Type SAVE to write these settings",
      "options": {
        "token": "tok_cfg_save",
        "defaultValue": "NO"
      }
    }
  },
  "dataSources": {
    "ds_ai_current": {
      "type": "ds.search",
      "name": "Saved AI config",
      "options": {
        "query": "| inputlookup dq_agent_ai_config\n| where stanza=\"default\"\n| head 1\n| eval used_ui=if(updated_at=\"0\" OR isnull(updated_at), 0, 1)\n| eval mode=if(used_ui=0, \"`exec_health_ai_mode`\", coalesce(mode, \"off\"))\n| eval provider=if(used_ui=0, \"`exec_health_ai_provider`\", coalesce(provider, \"none\"))\n| eval model=if(used_ui=0, \"`exec_health_ai_model`\", coalesce(model, \"none\"))\n| eval endpoint=if(used_ui=0, \"`exec_health_ai_endpoint`\", coalesce(endpoint, \"none\"))\n| eval inbox_index=coalesce(inbox_index, \"_internal\")\n| eval inbox_sourcetype=coalesce(inbox_sourcetype, \"derek_health_ai_unconfigured\")\n| lookup dq_agent_ai_providers provider OUTPUT provider_label, default_endpoint, notes\n| eval endpoint=if(endpoint=\"none\" OR endpoint=\"\", coalesce(default_endpoint, \"none\"), endpoint)\n| eval ai_status=case(mode=\"provider\" AND provider!=\"none\" AND provider!=\"\", \"PROVIDER\", mode=\"provider\", \"MISCONFIG\", 1=1, \"LOCAL\")\n| eval status_color=case(ai_status=\"PROVIDER\", \"YELLOW\", ai_status=\"MISCONFIG\", \"RED\", 1=1, \"GREEN\")\n| eval _color_rank=case(ai_status=\"MISCONFIG\", 1, ai_status=\"PROVIDER\", 2, 1=1, 3)\n| table ai_status, status_color, mode, provider, provider_label, model, endpoint, inbox_index, inbox_sourcetype, notes, _color_rank",
        "refresh": "30s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_providers": {
      "type": "ds.search",
      "name": "Provider catalog",
      "options": {
        "query": "| inputlookup dq_agent_ai_providers | eval _color_rank=3 | table provider, provider_label, default_endpoint, notes, _color_rank",
        "refresh": "5m",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_save": {
      "type": "ds.search",
      "name": "Save control",
      "options": {
        "query": "| makeresults\n| eval confirm=\"$tok_cfg_save$\", mode=\"$tok_cfg_mode$\", provider=\"$tok_cfg_provider$\"\n| eval ready=if(confirm=\"SAVE\" AND (mode=\"off\" OR (mode=\"provider\" AND provider!=\"none\" AND provider!=\"\")), 1, 0)\n| eval button_label=if(ready=1, \"CLICK TO SAVE CONFIG\", \"TYPE SAVE TO WRITE SETTINGS\")\n| eval button_color=if(ready=1, \"YELLOW\", \"N/A\")\n| table button_label, button_color, ready",
        "refresh": "30s",
        "refreshType": "delay",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# AI provider setup\nChoose how Derek+ talks to a model. This page stores **mode, provider, model, endpoint, and HEC inbox** only. **Never type API keys, HEC tokens, or webhook URLs here** \u2014 they are searchable. Put secrets in your gateway environment or Splunk **storage/passwords**.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_status": {
      "type": "splunk.singlevalue",
      "title": "Current mode",
      "dataSources": {
        "primary": "ds_ai_current"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"ai_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"ai_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          },
          {
            "match": "LOCAL",
            "value": "#53A051"
          },
          {
            "match": "PROVIDER",
            "value": "#F8BE34"
          },
          {
            "match": "MISCONFIG",
            "value": "#DC4E41"
          },
          {
            "match": "WAIT",
            "value": "#6B6B6B"
          }
        ]
      }
    },
    "viz_steps": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## After you save\n1. Enable **Exec Health - AI provider dispatch**.\n2. On that search, add a **webhook** in Splunk Web to your gateway (OpenAI, Cisco AI Defense, Azure, or `tools/ai_gateway_example.py`).\n3. Point the gateway at this HEC index/sourcetype.\n4. Open **Derek+ Data Quality Agent**, review a finding, type **ASK**, press **Run**.\nCisco endpoint looks like `https://gateway.aidefense.security.cisco.com/<tenant>/connections/<conn>/v1/chat/completions`.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_current": {
      "type": "splunk.table",
      "title": "Saved integration settings (no secrets)",
      "dataSources": {
        "primary": "ds_ai_current"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "count": 5,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "auto",
            "newTab": true
          }
        }
      ]
    },
    "viz_providers": {
      "type": "splunk.table",
      "title": "Supported providers",
      "dataSources": {
        "primary": "ds_ai_providers"
      },
      "showLastUpdated": true,
      "showProgressBar": true,
      "options": {
        "count": 10,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        }
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
            "value": "#5C1A1A"
          },
          {
            "from": 1.5,
            "to": 2.5,
            "value": "#5C4A12"
          },
          {
            "from": 2.5,
            "to": 4,
            "value": "#14301A"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "auto",
            "newTab": true
          }
        }
      ]
    },
    "viz_save": {
      "type": "splunk.singlevalue",
      "title": "Save (opens Search; you must press Run)",
      "dataSources": {
        "primary": "ds_ai_save"
      },
      "showLastUpdated": true,
      "showProgressBar": false,
      "options": {
        "majorValue": "> primary | seriesByName(\"button_label\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"button_color\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 22
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          },
          {
            "match": "LOCAL",
            "value": "#53A051"
          },
          {
            "match": "PROVIDER",
            "value": "#F8BE34"
          },
          {
            "match": "MISCONFIG",
            "value": "#DC4E41"
          },
          {
            "match": "WAIT",
            "value": "#6B6B6B"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "custom",
            "newTab": true,
            "query": "| inputlookup dq_agent_ai_config | eval src=1 | append [ | makeresults | eval confirm=\"$tok_cfg_save$\" | eval mode=lower(\"$tok_cfg_mode$\") | eval mode=if(mode=\"provider\", \"provider\", \"off\") | eval provider=replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\") | eval provider=if(provider=\"openai\" OR provider=\"cisco\" OR provider=\"azure\" OR provider=\"anthropic\" OR provider=\"custom\", provider, \"none\") | eval model=replace(lower(\"$tok_cfg_model$\"), \"[^a-z0-9._-]\", \"\") | eval model=if(model=\"\" OR isnull(model), \"none\", model) | eval endpoint=replace(\"$tok_cfg_endpoint$\", \"[^-A-Za-z0-9:/.?&=]\", \"\") | eval endpoint=if(endpoint=\"\" OR isnull(endpoint), \"none\", endpoint) | eval inbox_index=replace(\"$tok_cfg_inbox_index$\", \"[^A-Za-z0-9_]\", \"\") | eval inbox_index=if(inbox_index=\"\" OR isnull(inbox_index), \"_internal\", inbox_index) | eval inbox_sourcetype=replace(\"$tok_cfg_inbox_sourcetype$\", \"[^A-Za-z0-9_]\", \"\") | eval inbox_sourcetype=if(inbox_sourcetype=\"\" OR isnull(inbox_sourcetype), \"derek_health_ai_unconfigured\", inbox_sourcetype) | where confirm=\"SAVE\" AND (mode=\"off\" OR (mode=\"provider\" AND provider!=\"none\")) | eval stanza=\"default\", src=2, updated_by=\"human_dashboard\", updated_at=strftime(now(), \"%Y-%m-%d %H:%M:%S\"), note=\"ui_config\" | table stanza, mode, provider, model, endpoint, inbox_index, inbox_sourcetype, updated_by, updated_at, note, src ] | sort stanza, -src | dedup stanza | fields - src | outputlookup dq_agent_ai_config"
          }
        }
      ]
    },
    "viz_footer": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Saving writes `lookups/dq_agent_ai_config.csv` on this search head. It does not call a model and does not change `inputs.conf`. Webhook URLs and API keys never belong in this lookup.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    }
  },
  "layout": {
    "type": "grid",
    "structure": [
      {
        "item": "viz_header",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 140
        }
      },
      {
        "item": "viz_status",
        "type": "block",
        "position": {
          "x": 0,
          "y": 140,
          "w": 300,
          "h": 180
        }
      },
      {
        "item": "viz_steps",
        "type": "block",
        "position": {
          "x": 300,
          "y": 140,
          "w": 900,
          "h": 180
        }
      },
      {
        "item": "viz_current",
        "type": "block",
        "position": {
          "x": 0,
          "y": 320,
          "w": 1200,
          "h": 200
        }
      },
      {
        "item": "viz_providers",
        "type": "block",
        "position": {
          "x": 0,
          "y": 520,
          "w": 1200,
          "h": 240
        }
      },
      {
        "item": "viz_save",
        "type": "block",
        "position": {
          "x": 0,
          "y": 760,
          "w": 400,
          "h": 200
        }
      },
      {
        "item": "viz_footer",
        "type": "block",
        "position": {
          "x": 400,
          "y": 760,
          "w": 800,
          "h": 200
        }
      }
    ],
    "globalInputs": [
      "input_cfg_mode",
      "input_cfg_provider",
      "input_cfg_model",
      "input_cfg_endpoint",
      "input_cfg_inbox_index",
      "input_cfg_inbox_sourcetype",
      "input_cfg_save"
    ]
  }
}
